VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.31,"Lecture fifteen. High-performance computing. Many small workers, wired together, run one big job."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":40.008,"caps":[[0.5,6.91,"On a laptop, the storm model takes 3 days."],[7.16,15.65,"Three things make a system fast: processing, communication, I/O."],[15.9,24.87,"One giant machine, or many computers on a network."],[25.12,32.01,"A cluster has nodes; nodes hold processors; processors hold cores."],[32.26,38.83,"4 × 2 × 8 = 64 cores working at once."]],"warp":[[0,0],[0.5,0.4],[7.16,3],[15.9,6.5],[25.12,9.9],[32.26,12.6],[40.008,15]]},{"dur":26.773,"caps":[[0.5,5.71,"One sum on decimal numbers is a floating-point operation."],[5.96,10.05,"FLOPS: how many of them a machine does per second."],[10.3,16.15,"Giga, tera, peta, exa: each rung is 1000 times the last."],[16.4,25.13,"A server CPU: 1 to 2 TFLOPS. A data-centre GPU: over 1000."]],"warp":[[0,0],[0.5,0.4],[5.96,3.2],[10.3,5.8],[16.4,8.9],[26.773,13]]},{"dur":18.39,"caps":[[0.5,5.47,"Nodes are joined by a LAN, a local-area network."],[5.72,11.01,"Each step, every node swaps border weather with its neighbours."],[11.26,17.03,"A slow network leaves fast cores waiting for data."]],"warp":[[0,0],[0.5,0.4],[5.72,3.4],[11.26,6.5],[18.39,10]]},{"dur":21.501,"caps":[[0.5,5.63,"Moore's law: transistors on a chip double about every two years."],[5.88,12.05,"1, 2, 4, 8, 16. Ten years: 32 times as many."],[12.3,16.39,"Now chips are hitting limits and falling behind."],[16.64,20.81,"So new speed comes from more cores and more nodes."]],"warp":[[0,0],[0.5,0.4],[5.88,3.6],[12.3,6.1],[16.64,9.3],[21.501,13]]},{"dur":29.931,"caps":[[0.5,6.59,"10 sums must run in order. 100 more can be shared."],[6.84,11.01,"On 1 processor: 110 sums in a row."],[11.26,18.15,"On 10 processors the 100 split ten ways. The 10 do not."],[18.4,24.25,"Time of 20 sums: a speedup of 5.5, not 10."],[24.5,28.67,"The sequential part sets the limit."]],"warp":[[0,0],[0.5,0.4],[6.84,3.4],[11.26,6],[18.4,9.4],[24.5,11.8],[29.931,14]]},{"dur":25.078,"caps":[[0.5,6.27,"p: the share of time that can be shared. s: its speedup."],[6.52,13.41,"90% shareable: 8 processors give 4.7×, 64 give 8.8×."],[13.66,18.79,"It can never beat 1 ÷ 0.1 = 10×."],[19.04,23.77,"50% shareable: even 32 processors stay below 2×."]],"warp":[[0,0],[0.5,0.4],[6.52,3.4],[13.66,6.6],[19.04,9.2],[25.078,13]]},{"dur":30.093,"caps":[[0.5,9.95,"Owning it costs admins, support, power and cooling."],[10.2,17.41,"A resource manager allocates hardware and schedules the work."],[17.66,22.23,"It starts the work on many nodes and monitors it."],[22.48,28.25,"Each job waits in a queue that sets the order."]],"warp":[[0,0],[0.5,0.4],[10.2,3.4],[17.66,6.8],[22.48,9.6],[30.093,13]]},{"dur":28.444,"caps":[[0.5,8.03,"Slurm: Kestrel's resource manager and scheduler."],[8.28,16.69,"Partitions: cpu has 6 nodes, gpu has 2. Each is a queue."],[16.94,23.19,"The high-priority job takes 4 nodes, the next takes 2."],[23.44,27.13,"No nodes left: the third job waits."]],"warp":[[0,0],[0.5,0.4],[8.28,3.2],[16.94,6.4],[23.44,9.6],[28.444,13]]},{"dur":26.866,"caps":[[0.5,7.71,"sbatch submits job 4021. Nodes are busy, so it waits."],[7.96,14.13,"squeue shows it pending, PD. Then it gets n1 to n4."],[14.38,19.19,"srun launches a job step: 4 tasks, one per node."],[19.44,26.17,"sacct shows the record: completed in 5 h 12 min."]],"warp":[[0,0],[0.5,0.4],[7.96,3.6],[14.38,7.6],[19.44,11],[26.866,15]]},{"dur":20.015,"caps":[],"warp":[[0,0],[0.5,0.9],[6.92,2],[12.06,3.1],[20.015,9]]}]};
